CREATE TABLE public.profiles (id uuid PRIMARY KEY REFERENCES auth.users(id) ON DELETE CASCADE, display_name text NOT NULL DEFAULT '', company text NOT NULL DEFAULT '', phone text NOT NULL DEFAULT '', avatar_url text NOT NULL DEFAULT '', created_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT, UPDATE ON public.profiles TO authenticated;
GRANT ALL ON public.profiles TO service_role;
ALTER TABLE public.profiles ENABLE ROW LEVEL SECURITY;
CREATE TABLE public.portal_roles (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), user_id uuid NOT NULL REFERENCES public.profiles(id) ON DELETE CASCADE, role text NOT NULL CHECK(role IN ('client','provider','operations','finance','customer')), UNIQUE(user_id,role));
GRANT SELECT ON public.portal_roles TO authenticated;
GRANT ALL ON public.portal_roles TO service_role;
ALTER TABLE public.portal_roles ENABLE ROW LEVEL SECURITY;
CREATE OR REPLACE FUNCTION public.portal_can(permission text) RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT public.has_role(auth.uid(),'admin') OR EXISTS(SELECT 1 FROM public.portal_roles WHERE user_id=auth.uid() AND ((role='operations' AND permission IN ('operations','reports')) OR (role='finance' AND permission='finance') OR (role='customer' AND permission IN ('clients','contracts','complaints')))) $$;
REVOKE ALL ON FUNCTION public.portal_can(text) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION public.portal_can(text) TO authenticated;
CREATE POLICY profile_read ON public.profiles FOR SELECT TO authenticated USING(id=auth.uid() OR public.portal_can('clients') OR public.portal_can('operations') OR public.portal_can('finance'));
CREATE POLICY profile_update ON public.profiles FOR UPDATE TO authenticated USING(id=auth.uid() OR public.has_role(auth.uid(),'admin')) WITH CHECK(id=auth.uid() OR public.has_role(auth.uid(),'admin'));
CREATE POLICY portal_roles_read ON public.portal_roles FOR SELECT TO authenticated USING(user_id=auth.uid() OR public.has_role(auth.uid(),'admin'));
CREATE OR REPLACE FUNCTION public.create_portal_profile() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN INSERT INTO public.profiles(id,display_name) VALUES(new.id,coalesce(new.raw_user_meta_data->>'full_name','')); INSERT INTO public.portal_roles(user_id,role) VALUES(new.id,'client'); RETURN new; END $$;
CREATE TRIGGER on_auth_portal_profile AFTER INSERT ON auth.users FOR EACH ROW EXECUTE FUNCTION public.create_portal_profile();
INSERT INTO public.profiles(id,display_name) SELECT id,coalesce(raw_user_meta_data->>'full_name','') FROM auth.users ON CONFLICT DO NOTHING;
INSERT INTO public.portal_roles(user_id,role) SELECT id,'client' FROM public.profiles ON CONFLICT DO NOTHING;
REVOKE INSERT, UPDATE, DELETE ON public.user_roles FROM authenticated, anon;